CREATE TABLE IF NOT EXISTS ducks_coffee_shop_product_table (id BIGSERIAL PRIMARY KEY, "name" CITEXT NOT NULL, description TEXT NULL, price DECIMAL(10, 2) NOT NULL, category_id BIGINT NOT NULL, "constructors" BIGINT NULL, shop_id BIGINT NOT NULL, sizes JSON NOT NULL, "imageUrl" TEXT NOT NULL, carbohydrates VARCHAR(15) NULL, protein VARCHAR(15) NULL, fats VARCHAR(15) NULL, calories VARCHAR(15) NULL)